/**
 * dsh-ide — monaco codicon font as an inline data URL.
 *
 * The aggregated monaco CSS references url(...codicon.ttf); inside the
 * plugin's injected <style> that relative path cannot resolve, so folding
 * arrows / codicon glyphs render as blanks. Embedding the font as base64
 * keeps every codicon working offline.
 */
export const CODIconFontDataUrl = "data:font/ttf;base64,";